RUN_FMP_PREFLIGHT = False  # @param {type:"boolean"}
from src.data import FMPClient, DataAccessError, preflight

if RUN_FMP_PREFLIGHT:
    try:
        client = FMPClient(cache_dir=RUN_ROOT / "fmp_cache")
        fmp_access = preflight(client)
        (RUN_ROOT / "fmp_access_report.json").write_text(json.dumps(fmp_access, indent=2))
        print(json.dumps(fmp_access, indent=2))
        if not fmp_access["ok"]:
            print("Adjusted data access did not pass. Resolve the reported access/schema issue before download.")
    except DataAccessError as exc:
        client = None
        print(json.dumps(exc.as_dict(), indent=2))
        print("Check the secret's name, notebook-access toggle, and your FMP endpoint entitlements.")
else:
    print("FMP access not checked. Add the secret, enable RUN_FMP_PREFLIGHT, and rerun this cell.")

RUN_PROFILE = False  # @param {type:"boolean"}
PROFILE_STEPS = 100  # @param {type:"integer"}
BATCH_DATES = 16  # @param {type:"integer"}
STOCKS_PER_DATE = 32  # @param {type:"integer"}
ACCUMULATION_STEPS = 2  # @param {type:"integer"}
BUDGET_HOURS = 4.0  # @param {type:"number"}
budget = None

if RUN_PROFILE:
    if panel is None:
        raise RuntimeError("Load the diagnostic panel first.")
    if DEVICE != "cuda":
        raise RuntimeError("Select a GPU runtime before real-data profiling and training.")
    if PROFILE_STEPS < 10:
        raise ValueError("Use at least 10 timed updates for an initial profile.")
    for variant in VARIANTS:
        profiles[variant] = profile_variant(
            panel, variant, batch_dates=BATCH_DATES, stocks=STOCKS_PER_DATE,
            seed=42, device=DEVICE, profile_steps=PROFILE_STEPS,
            accumulation_steps=ACCUMULATION_STEPS)
        print(variant, json.dumps(profiles[variant], indent=2))
    budget = budget_from_profiles(profiles, budget_hours=BUDGET_HOURS,
                                  screen_steps=500, total_steps=2500)
    experiment_settings = {
        "batch_dates": BATCH_DATES, "stocks": STOCKS_PER_DATE,
        "accumulation_steps": ACCUMULATION_STEPS,
        "dataset_fingerprint": panel.metadata["dataset_fingerprint"],
        "budget": budget,
    }
    (RUN_ROOT / "profiles.json").write_text(json.dumps(profiles, indent=2))
    (RUN_ROOT / "experiment_settings.json").write_text(json.dumps(experiment_settings, indent=2))
    print("Matched schedule:", json.dumps(budget, indent=2))
else:
    settings_path = RUN_ROOT / "experiment_settings.json"
    if settings_path.exists():
        experiment_settings = json.loads(settings_path.read_text())
        budget = experiment_settings["budget"]
        BATCH_DATES = experiment_settings["batch_dates"]
        STOCKS_PER_DATE = experiment_settings["stocks"]
        ACCUMULATION_STEPS = experiment_settings["accumulation_steps"]
        print("Loaded existing schedule:", json.dumps(budget, indent=2))
    else:
        print("Profiling skipped; no experiment budget exists yet.")

RUN_SCREEN = False  # @param {type:"boolean"}
if RUN_SCREEN:
    if panel is None or budget is None:
        raise RuntimeError("Load data and create a profiled budget first.")
    if DEVICE != "cuda":
        raise RuntimeError("A GPU runtime is required for this real-data screen.")
    if experiment_settings["dataset_fingerprint"] != panel.metadata["dataset_fingerprint"]:
        raise RuntimeError("The saved budget belongs to a different dataset. Re-profile before training.")
    for variant in VARIANTS:
        run_dir = RUN_ROOT / f"variant_{variant}_seed42"
        resume = any(run_dir.glob("step_*.pt"))
        screen_results[variant] = run_variant(
            panel, variant, run_dir, seed=42,
            screen_steps=budget["screen_steps"], total_steps=budget["total_steps"],
            batch_dates=BATCH_DATES, stocks=STOCKS_PER_DATE, device=DEVICE,
            accumulation_steps=ACCUMULATION_STEPS, resume=resume,
            stop_at=budget["screen_steps"])
        print(variant, "completed updates:", screen_results[variant]["optimizer_step"],
              "encoder:", screen_results[variant]["encoder_export"])
else:
    print("A–E screen skipped. Enable RUN_SCREEN after reviewing the profiled schedule.")

RUN_DEVELOPMENT_EVAL = False  # @param {type:"boolean"}
EVAL_BATCH_DATES = 16  # @param {type:"integer"}
BOOTSTRAP_SAMPLES = 500  # @param {type:"integer"}
if RUN_DEVELOPMENT_EVAL:
    if panel is None or budget is None:
        raise RuntimeError("Load the data and matched settings first.")
    for variant in VARIANTS:
        run_dir = RUN_ROOT / f"variant_{variant}_seed42"
        snapshot = run_dir / f"encoder_step_{budget['screen_steps']:06d}.pt"
        if not snapshot.exists():
            raise RuntimeError(f"Missing matched screen snapshot for {variant}: {snapshot}")
        report = evaluate_variant(
            panel, run_dir, device=DEVICE, years=(2019, 2020, 2021), horizon=5,
            batch_size=EVAL_BATCH_DATES, bootstrap_samples=BOOTSTRAP_SAMPLES,
            snapshot=snapshot)
        development_reports[variant] = report
        metrics = report["metrics"]["trained_encoder"]["development"]
        print(variant, json.dumps({key: metrics[key] for key in ("mean_daily_rank_ic", "rank_ic_95ci_date_blocks", "valid_ic_dates", "yearly")}, indent=2))
    (RUN_ROOT / "development_reports.json").write_text(json.dumps(development_reports, indent=2))
else:
    reports_path = RUN_ROOT / "development_reports.json"
    if reports_path.exists():
        development_reports = json.loads(reports_path.read_text())
        print("Loaded saved development reports.")
    else:
        print("Development evaluation skipped. Complete matched screens first.")

RUN_FREEZE_SELECTION = False  # @param {type:"boolean"}
selection_path = RUN_ROOT / "frozen_selection.json"
selection = None
if selection_path.exists():
    selection = json.loads(selection_path.read_text())
    selected_variant = selection["variant"]
    print("Using existing frozen choice:", selected_variant)
elif RUN_FREEZE_SELECTION:
    if any(name not in development_reports for name in VARIANTS):
        raise RuntimeError("Evaluate all five matched screens before selecting.")
    scores = {
        name: development_reports[name]["metrics"]["trained_encoder"]["development"]["mean_daily_rank_ic"]
        for name in ("B", "C", "D", "E")
    }
    valid = {name: score for name, score in scores.items() if score is not None}
    if len(valid) != 4:
        raise RuntimeError("A future variant has no valid development IC. Inspect coverage and constant representations.")
    best = max(valid, key=valid.get)
    interval = development_reports[best]["metrics"]["trained_encoder"]["development"]["rank_ic_95ci_date_blocks"]
    margin = (interval[1] - interval[0]) / 3.92 if interval is not None else 0.0
    close = {name for name, score in valid.items() if score >= valid[best] - margin}
    selected_variant = next(name for name in ("B", "C", "D", "E") if name in close)
    selection = {
        "variant": selected_variant, "development_scores": scores,
        "highest_score_variant": best, "approximate_one_se_margin": margin,
        "selection_rule": "development IC; approximate one-SE preference B, C, D, E",
        "screen_steps": budget["screen_steps"], "total_steps": budget["total_steps"],
        "dataset_fingerprint": panel.metadata["dataset_fingerprint"],
        "historical_evaluation_consulted": False,
        "point_in_time_verified": False,
    }
    selection_path.write_text(json.dumps(selection, indent=2))
    print(json.dumps(selection, indent=2))
    chosen = development_reports[selected_variant]["metrics"]
    print("Chosen trained/random/raw development IC:",
          {name: chosen[name]["development"]["mean_daily_rank_ic"]
           for name in ("trained_encoder", "random_encoder", "raw_features")})
else:
    print("No frozen choice yet. Enable RUN_FREEZE_SELECTION after reviewing development results.")

RUN_CONTINUE_AND_REPEAT = False  # @param {type:"boolean"}
RUN_FINAL_DEVELOPMENT_EVAL = False  # @param {type:"boolean"}
final_results = {}
final_development_reports = {}
if RUN_CONTINUE_AND_REPEAT:
    if selection is None or panel is None or budget is None:
        raise RuntimeError("Load data, matched settings, and a frozen selection first.")
    if selection["dataset_fingerprint"] != panel.metadata["dataset_fingerprint"]:
        raise RuntimeError("The frozen choice belongs to a different dataset.")
    if DEVICE != "cuda":
        raise RuntimeError("Select a GPU runtime before the longer training runs.")
    for seed in (42, 43):
        run_dir = RUN_ROOT / f"variant_{selected_variant}_seed{seed}"
        final_results[seed] = run_variant(
            panel, selected_variant, run_dir, seed=seed,
            screen_steps=budget["screen_steps"], total_steps=budget["total_steps"],
            batch_dates=BATCH_DATES, stocks=STOCKS_PER_DATE, device=DEVICE,
            accumulation_steps=ACCUMULATION_STEPS,
            resume=any(run_dir.glob("step_*.pt")), stop_at=budget["total_steps"])
        print("Seed", seed, "encoder:", final_results[seed]["encoder_export"])
else:
    print("Continuation and seed repeat skipped.")

if RUN_FINAL_DEVELOPMENT_EVAL:
    if selection is None or panel is None or budget is None:
        raise RuntimeError("A frozen choice, panel, and settings are required.")
    for seed in (42, 43):
        run_dir = RUN_ROOT / f"variant_{selected_variant}_seed{seed}"
        snapshot = run_dir / f"encoder_step_{budget['total_steps']:06d}.pt"
        if not snapshot.exists():
            raise RuntimeError(f"Finish seed {seed} at the matched total budget first.")
        final_development_reports[seed] = evaluate_variant(
            panel, run_dir, device=DEVICE, years=(2019, 2020, 2021), horizon=5,
            batch_size=EVAL_BATCH_DATES, bootstrap_samples=BOOTSTRAP_SAMPLES,
            snapshot=snapshot)
        print("Seed", seed, json.dumps(
            {key: final_development_reports[seed]["metrics"]["trained_encoder"]["development"][key] for key in ("mean_daily_rank_ic", "rank_ic_95ci_date_blocks", "valid_ic_dates", "yearly")}, indent=2))
    (RUN_ROOT / "final_development_reports.json").write_text(json.dumps(final_development_reports, indent=2))
else:
    print("Final development evaluation skipped.")

RUN_HISTORICAL_EVALUATION = False  # @param {type:"boolean"}
RUN_SECONDARY_HORIZONS = False  # @param {type:"boolean"}
historical_reports = {}
if RUN_HISTORICAL_EVALUATION:
    if selection is None or panel is None or budget is None:
        raise RuntimeError("Freeze the choice and finish both training seeds first.")
    if not (RUN_ROOT / "final_development_reports.json").exists():
        raise RuntimeError("Evaluate both completed seeds on development before historical evaluation.")
    for seed in (42, 43):
        run_dir = RUN_ROOT / f"variant_{selected_variant}_seed{seed}"
        snapshot = run_dir / f"encoder_step_{budget['total_steps']:06d}.pt"
        if not snapshot.exists():
            raise RuntimeError(f"Missing completed seed {seed} snapshot.")
        for horizon in ((5, 1, 20) if RUN_SECONDARY_HORIZONS else (5,)):
            report = evaluate_variant(
                panel, run_dir, device=DEVICE, years=(2022, 2023, 2024, 2025),
                horizon=horizon, batch_size=EVAL_BATCH_DATES,
                bootstrap_samples=BOOTSTRAP_SAMPLES, snapshot=snapshot)
            historical_reports[f"seed{seed}_h{horizon}"] = report
            print("Seed", seed, "horizon", horizon, json.dumps(
                {key: report["metrics"]["trained_encoder"]["historical_evaluation"][key] for key in ("mean_daily_rank_ic", "rank_ic_95ci_date_blocks", "valid_ic_dates", "yearly")}, indent=2))
    (RUN_ROOT / "historical_reports.json").write_text(json.dumps(historical_reports, indent=2))
else:
    print("Historical evaluation remains locked. No historical metrics were requested.")

DOWNLOAD_RESULT_BUNDLE = False  # @param {type:"boolean"}
if DOWNLOAD_RESULT_BUNDLE:
    import zipfile
    if selection is None or budget is None:
        raise RuntimeError("Select a model before making its result bundle.")
    bundle = RUN_ROOT / "selected_encoder_and_reports.zip"
    paths = []
    for name in ("frozen_selection.json", "feature_notes.json", "experiment_settings.json",
                 "fmp_access_report.json", "download_report.json", "development_reports.json",
                 "final_development_reports.json", "historical_reports.json"):
        path = RUN_ROOT / name
        if path.exists():
            paths.append(path)
    for seed in (42, 43):
        run_dir = RUN_ROOT / f"variant_{selected_variant}_seed{seed}"
        export = run_dir / f"encoder_step_{budget['total_steps']:06d}.pt"
        if export.exists():
            paths.append(export)
        for name in ("run_metadata.json", "run_result.json", "training_metrics.json"):
            if (run_dir / name).exists():
                paths.append(run_dir / name)
        paths.extend(run_dir.rglob("evaluation_report.json"))
        paths.extend(run_dir.rglob("predictions.csv"))
        paths.extend(run_dir.rglob("peer_partitions.json"))
    if not any(path.suffix == ".pt" for path in paths):
        raise RuntimeError("No final compact encoder exists yet; finish continuation first.")
    with zipfile.ZipFile(bundle, "w", zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(set(paths)):
            archive.write(path, path.relative_to(RUN_ROOT))
    print("Created:", bundle, "bytes:", bundle.stat().st_size)
    from google.colab import files
    files.download(str(bundle))
else:
    print("Download skipped. Enable DOWNLOAD_RESULT_BUNDLE when the selected encoder is ready.")
